package com.dentalclinic.patientcare.repository; import com.dentalclinic.patientcare.entity.PatientCareRecord;import org.springframework.data.jpa.repository.JpaRepository;import java.time.LocalDate;import java.util.List; public interface PatientCareRecordRepository extends JpaRepository<PatientCareRecord,Long>{List<PatientCareRecord> findByFullNameContainingIgnoreCase(String name);List<PatientCareRecord> findByNextRecallDateBetween(LocalDate from,LocalDate to);List<PatientCareRecord> findByActive(Boolean active);}